import{_ as t,o,c as d,a2 as a}from"./chunks/framework.Boholvbs.js";const m=JSON.parse('{"title":"Tools reference","description":"Every tool the agent can call — parameters, caps, defaults, availability gates: read, edit, write, apply_patch, bash, glob, grep, task, todowrite, question, plan, skill, webfetch, websearch, lsp, sessions, jobs, code-mode.","frontmatter":{"title":"Tools reference","description":"Every tool the agent can call — parameters, caps, defaults, availability gates: read, edit, write, apply_patch, bash, glob, grep, task, todowrite, question, plan, skill, webfetch, websearch, lsp, sessions, jobs, code-mode."},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md"}'),r={name:"reference/tools.md"};function s(i,e,c,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<p>Tools are the agent&#39;s hands. Each one is permission-gated by its name (see the <code>permission</code> table&#39;s known keys), and each row here is verified against the tool source. &quot;Gate&quot; = when the tool exists at all; most are always available.</p><h2 id="file-code" tabindex="-1">File &amp; code <a class="header-anchor" href="#file-code" aria-label="Permalink to &quot;File &amp; code&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Params</th><th>Behavior &amp; limits</th></tr></thead><tbody><tr><td><strong>read</strong></td><td><code>filePath</code> (abs), <code>offset?</code>, <code>limit?</code></td><td>Text: up to 2,000 lines, lines cut at 2,000 chars, 50 KB per response. Directories listed one-per-line (<code>/</code> suffix). Images (jpeg/png/gif/webp) and PDFs come back as attachments. Binary refused. Near-miss names suggest up to 3 candidates. Warms LSP. <code>*.env</code> asks by default.</td></tr><tr><td><strong>write</strong></td><td><code>filePath</code>, <code>content</code></td><td>Create/overwrite (read-first is required by convention, restated every session). Formats after write, appends LSP diagnostics for the file + up to 5 other open files.</td></tr><tr><td><strong>edit</strong></td><td><code>filePath</code>, <code>oldString</code>, <code>newString</code>, <code>replaceAll?</code></td><td>Exact-match string replacement with fuzzy fallback ladder (line-trimmed, block-anchored ≥0.65 similarity, whitespace-normalized, indentation-flexible, escape-normalized, trimmed-boundary, context-aware, multi-occurrence). Refuses spans much larger than <code>oldString</code>. Per-file locking, CRLF/BOM preserved. Collision notice when the file changed since read. Post-edit diagnostics appended.</td></tr><tr><td><strong>apply_patch</strong></td><td><code>patchText</code></td><td><code>*** Begin/End Patch</code> with <code>Add/Delete/Update File</code> (+ <code>Move to</code>) sections. <strong>Replaces edit/write on GPT-family models</strong> (auto-detected).</td></tr></tbody></table><h2 id="execution-search" tabindex="-1">Execution &amp; search <a class="header-anchor" href="#execution-search" aria-label="Permalink to &quot;Execution &amp; search&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Params</th><th>Behavior &amp; limits</th></tr></thead><tbody><tr><td><strong>bash</strong></td><td><code>command</code>, <code>workdir?</code>, <code>timeout?</code> ms, <code>background?</code></td><td>Default timeout 2 minutes (<code>PRIORICODE_EXPERIMENTAL_BASH_DEFAULT_TIMEOUT_MS</code> overrides). Persistent shell per session. Output truncated at the same 2,000-line/50 KB wall — full text spilled to a file with the path given. <code>background: true</code> → job id + output file (see <strong>jobs</strong>). Tree-sitter parses file-touching args (<code>rm</code>, <code>mv</code>, <code>cp</code>…) for <code>external_directory</code> enforcement. Honors <code>bashSandbox</code> on macOS/Linux (never for pwsh/cmd).</td></tr><tr><td><strong>glob</strong></td><td><code>pattern</code>, <code>path?</code></td><td>ripgrep-powered file matching, 100 results.</td></tr><tr><td><strong>grep</strong></td><td><code>pattern</code> (regex), <code>path?</code>, <code>include?</code></td><td>ripgrep content search, 100 matches, grouped by file with line numbers.</td></tr><tr><td><strong>jobs</strong></td><td><code>action: list|output|wait|kill</code>, <code>id?</code>, <code>cursor?</code>, <code>timeout?</code></td><td>Manage backgrounded shell jobs: incremental output via byte <code>cursor</code>, <code>wait</code> default 5 s (cap 600 s), kill for cleanup. Completion of a background job re-announces itself into the session.</td></tr></tbody></table><h2 id="delegation-planning" tabindex="-1">Delegation &amp; planning <a class="header-anchor" href="#delegation-planning" aria-label="Permalink to &quot;Delegation &amp; planning&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Params</th><th>Behavior &amp; limits</th></tr></thead><tbody><tr><td><strong>task</strong></td><td><code>description</code>, <code>prompt</code>, <code>subagent_type</code>, <code>task_id?</code> (resume), <code>background?</code></td><td>Spawns a child session as that subagent; available types listed live in the tool description. <code>subagent_depth</code> default 1 caps recursion. Children get <code>todowrite</code>/<code>task</code> denied unless configured. <code>background</code> requires <code>PRIORICODE_EXPERIMENTAL_BACKGROUND_SUBAGENTS</code>.</td></tr><tr><td><strong>todowrite</strong></td><td><code>todos[] {content, status, priority}</code></td><td>The visible plan tracker; exactly one <code>in_progress</code>, live updates. Statuses: <code>pending</code>/<code>in_progress</code>/<code>completed</code>/<code>cancelled</code>.</td></tr><tr><td><strong>question</strong></td><td><code>questions[] {question, header ≤30 chars, options[], multiple?, custom?}</code></td><td>Renders the tabbed picker UI; answers come back as label arrays. Gate: official clients or <code>PRIORICODE_ENABLE_QUESTION_TOOL</code>; <code>question</code> permission default-deny per agent.</td></tr><tr><td><strong>plan_enter</strong> / <strong>plan_exit</strong></td><td>none</td><td>Ask the user to switch build→plan / plan→build; approval injects the synthetic switch message. Defaults: denied except <code>build</code> may enter, <code>plan</code> may exit.</td></tr></tbody></table><h2 id="knowledge-web" tabindex="-1">Knowledge &amp; web <a class="header-anchor" href="#knowledge-web" aria-label="Permalink to &quot;Knowledge &amp; web&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Params</th><th>Behavior &amp; limits</th></tr></thead><tbody><tr><td><strong>webfetch</strong></td><td><code>url</code>, <code>format?</code> (<code>markdown</code>/<code>text</code>/<code>html</code>), <code>timeout?</code> s</td><td>30 s default (max 120), 5 MB cap, HTTP→HTTPS upgrade, Cloudflare-challenge retry with its own UA, images returned as attachments.</td></tr><tr><td><strong>websearch</strong></td><td><code>query</code>, <code>numResults?</code> (8), <code>livecrawl?</code>, <code>type?</code> (<code>auto/fast/deep</code>), <code>contextMaxCharacters?</code> (10,000)</td><td>Backends: Exa or Parallel over MCP; chosen by <code>PRIORICODE_WEBSEARCH_PROVIDER</code> / enable flags / deterministic session split. Gate: hosted PrioriCode provider or Exa/Parallel enabled.</td></tr><tr><td><strong>skill</strong></td><td><code>name</code></td><td>Loads a discovered skill&#39;s body into context (plus base dir + 10-file sample listing). Permission pattern = skill name.</td></tr><tr><td><strong>lsp</strong> <em>(experimental)</em></td><td><code>operation</code>, <code>filePath</code>, <code>line</code>, <code>character</code>, <code>query?</code></td><td>9 navigation ops (definition, references, hover, symbols, implementation, call hierarchy). Gate: <code>PRIORICODE_EXPERIMENTAL_LSP_TOOL</code>.</td></tr><tr><td><strong>sessions</strong></td><td><code>action: discover|send|ask|respond|wait|notify|claim|release</code>, + per-action params</td><td>Cross-session coordination (<a href="./../using/coordination.html">full page</a>): ask timeout default 60 s/max 300 s; notify expiry 12 h; permission pattern = action name.</td></tr></tbody></table><h2 id="conditional-special" tabindex="-1">Conditional &amp; special <a class="header-anchor" href="#conditional-special" aria-label="Permalink to &quot;Conditional &amp; special&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Notes</th></tr></thead><tbody><tr><td><strong>execute</strong> <em>(code mode, experimental)</em></td><td>One confined script that calls your MCP catalog as <code>server.tool(...)</code>; JSON values only at the boundary; direct MCP tools are replaced by this single entry when <code>PRIORICODE_EXPERIMENTAL_CODE_MODE</code> is on. Per-call permission checks still run.</td></tr><tr><td><strong>list_mcp_resources / list_mcp_resource_templates / read_mcp_resource</strong></td><td>Exist only while a connected MCP server advertises resources; read permission is <code>mcp:&lt;server&gt;:&lt;uri&gt;</code>; binary attachments limited to pdf/gif/jpeg/png/webp ≤10 MB.</td></tr><tr><td><strong>invalid</strong></td><td>Internal placeholder for malformed model tool calls — never a capability, just how errors bounce back to the model.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>All tool output passes a shared truncation wall (defaults above): overflow is written to the tool-output directory and the path is given to the model, which can re-read it in slices. Nothing vanishes; only the context budget decides what stays visible.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../using/permissions.html">Permissions</a> — The gate every tool passes through. <ul><li><a href="./../using/coordination.html">Coordination</a> — The sessions tool in depth.</li><li><a href="./../extending/custom-tools.html">Custom tools</a> — Add a row to this table.</li></ul></li></ul>',14)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
